## 🔧 1. Python FastAPI Sidecar Server (`server.py`)

```python
#!/usr/bin/env python3
"""
Local sidecar engine using FastAPI.
Features:
- Background worker thread with thread-safe queue
- /api/health endpoint reporting RAM/VRAM usage
- Graceful shutdown on SIGINT/SIGTERM
"""

import asyncio
import logging
import os
import signal
import threading
import time
from collections import deque
from concurrent.futures import ThreadPoolExecutor
from typing import Deque

from fastapi import FastAPI
from pydantic import BaseModel
import psutil
import uvicorn

# Optional: Try to get VRAM info (requires GPU)
try:
    import GPUtil
    HAS_GPU = True
except ImportError:
    HAS_GPU = False
    logging.warning("GPUtil not available, VRAM monitoring disabled")

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

app = FastAPI(
    title="Local Sidecar Engine",
    description="Background worker with health reporting"
)

# Thread-safe queue for background tasks
class TaskQueue:
    def __init__(self):
        self._queue: Deque[str] = deque()
        self._lock = threading.Lock()

    def enqueue(self, task: str):
        with self._lock:
            self._queue.append(task)
            logger.debug(f"Enqueued task: {task}")

    def dequeue(self) -> str:
        with self._lock:
            if self._queue:
                return self._queue.popleft()
            return None

    @property
    def size(self) -> int:
        with self._lock:
            return len(self._queue)

# Global state
task_queue = TaskQueue()
shutdown_event = threading.Event()

class HealthResponse(BaseModel):
    status: str
    cpu_percent: float
    memory_gb: float
    memory_percent: float
    vram_mb: int = 0
    queue_size: int

def get_vram_usage() -> int:
    """Get VRAM usage in MB if GPU available."""
    if not HAS_GPU:
        return 0
    try:
        gpus = GPUtil.getGPUs()
        if gpus:
            # Return total VRAM of first GPU (assuming single-GPU setup)
            return gpus[0].memoryTotal
    except Exception as e:
        logger.warning(f"Failed to get VRAM: {e}")
    return 0

def background_worker():
    """Background thread that processes tasks from the queue."""
    logger.info("Background worker started")

    while not shutdown_event.is_set():
        try:
            task = task_queue.dequeue()
            if task is None:
                time.sleep(1)  # Wait for work
                continue

            # Simulate processing (replace with actual logic)
            logger.info(f"Processing task: {task}")
            time.sleep(2)  # Simulate work
            logger.info(f"Completed task: {task}")

        except Exception as e:
            logger.error(f"Worker error: {e}")

    logger.info("Background worker shutting down")

@app.on_event("startup")
async def startup_event():
    """Start background worker on app startup."""
    logger.info("Starting sidecar engine...")
    threading.Thread(target=background_worker, daemon=True).start()

@app.get("/api/health", response_model=HealthResponse)
def health_check():
    """Report system and queue health status."""
    process = psutil.Process(os.getpid())

    return HealthResponse(
        status="healthy" if not shutdown_event.is_set() else "shutting_down",
        cpu_percent=psutil.cpu_percent(interval=None),
        memory_gb=process.memory_info().rss / 1024 / 1024 / 1024,
        memory_percent=process.memory_percent(),
        vram_mb=get_vram_usage(),
        queue_size=task_queue.size
    )

@app.post("/api/queue")
def enqueue_task(task: str):
    """Add a task to the background queue."""
    task_queue.enqueue(task)
    return {"status": "enqueued", "task": task}

def signal_handler(sig, frame):
    """Handle graceful shutdown signals."""
    logger.info(f"Received signal {sig}, initiating shutdown...")
    shutdown_event.set()

async def main():
    # Set up signal handlers
    loop = asyncio.get_running_loop()
    for sig in (signal.SIGINT, signal.SIGTERM):
        loop.add_signal_handler(sig, lambda s=sig: signal_handler(s, None))

    logger.info("Starting FastAPI server on http://localhost:8000")
    config = uvicorn.Config(app, host="127.0.0.1", port=8000, log_level="info")
    server = uvicorn.Server(config)

    try:
        await server.serve()
    except KeyboardInterrupt:
        logger.info("Server interrupted")
    finally:
        logger.info("Shutting down gracefully")

if __name__ == "__main__":
    asyncio.run(main())
