## 🦀 2. Node.js Client (`client.js`)

```javascript
#!/usr/bin/env node
/**
 * Node.js client that spawns Python sidecar and polls health endpoint.
 * Features:
 * - Spawns the Python process
 * - Polls /api/health with exponential backoff
 * - Handles unexpected termination gracefully
 */

const { spawn } = require('child_process');
const axios = require('axios'); // npm install axios

class SidecarClient {
    constructor() {
        this.pythonProcess = null;
        this.isHealthy = false;
        this.maxRetries = 10;
        this.baseDelay = 1000; // Start with 1s
        this.currentRetry = 0;
    }

    spawnPythonServer() {
        return new Promise((resolve, reject) => {
            const scriptPath = require('path').join(__dirname, 'server.py');

            this.pythonProcess = spawn('python3', [scriptPath], {
                stdio: ['pipe', 'pipe', 'pipe'],
                detached: false,
                cwd: __dirname
            });

            let stdoutData = '';
            let stderrData = '';

            this.pythonProcess.stdout.on('data', (chunk) => {
                const text = chunk.toString();
                stdoutData += text;
                console.log('[Python]', text.trim());

                // Check if server is ready (you can customize this condition)
                if (text.includes('Starting FastAPI server')) {
                    resolve();
                }
            });

            this.pythonProcess.stderr.on('data', (chunk) => {
                stderrData += chunk.toString();
                console.error('[Python Error]', chunk.toString().trim());
            });

            this.pythonProcess.on('close', (code) => {
                if (!this.isHealthy && code !== 0) {
                    reject(new Error(`Python server exited with code ${code}`));
                }
            });

            this.pythonProcess.on('error', (err) => {
                reject(err);
            });
        });
    }

    async pollHealthWithBackoff() {
        const url = 'http://localhost:8000/api/health';

        while (!this.isHealthy && this.currentRetry < this.maxRetries) {
            try {
                console.log(`Polling health (attempt ${this.currentRetry + 1}...)`);

                const response = await axios.get(url, { timeout: 5000 });

                if (response.status === 200) {
                    const data = response.data;
                    this.isHealthy = data.status === 'healthy';

                    console.log('Health check result:', {
                        status: data.status,
                        cpu_percent: data.cpu_percent.toFixed(1),
                        memory_gb: data.memory_gb.toFixed(2),
                        queue_size: data.queue_size
                    });

                    if (this.isHealthy) {
                        console.log('✅ Sidecar is healthy!');
                        break;
                    }
                }

            } catch (error) {
                console.warn(`Health check failed: ${error.message}`);
            }

            // Exponential backoff with jitter
            const delay = this.baseDelay * Math.pow(2, this.currentRetry) + 
                         Math.random() * 1000; // Add jitter

            await new Promise(resolve => setTimeout(resolve, delay));
            this.currentRetry++;
        }

        if (!this.isHealthy) {
            throw new Error('Failed to connect to sidecar after max retries');
        }
    }

    async start() {
        console.log('🚀 Starting Python sidecar engine...');

        try {
            // Spawn the server
            await this.spawnPythonServer();

            // Poll until healthy
            await this.pollHealthWithBackoff();

            console.log('✅ Sidecar client ready!');

            // Optional: Keep polling periodically
            setInterval(async () => {
                try {
                    const response = await axios.get('http://localhost:8000/api/health', { timeout: 3000 });
                    if (response.data.status !== 'healthy') {
                        console.warn('⚠️ Sidecar reported non-healthy status');
                    }
                } catch (error) {
                    console.error('❌ Lost connection to sidecar:', error.message);
                    process.exit(1); // Or restart logic here
                }
            }, 5000);

        } catch (error) {
            console.error('❌ Failed to start sidecar:', error.message);

            if (this.pythonProcess) {
                this.pythonProcess.kill();
            }

            process.exit(1);
        }
    }

    shutdown() {
        if (this.pythonProcess && !this.pythonProcess.killed) {
            console.log('🛑 Shutting down Python server...');
            this.pythonProcess.kill();
        }
    }
}

// Handle graceful shutdown
process.on('SIGINT', () => {
    console.log('\n👋 Received SIGINT, shutting down gracefully...');
    client.shutdown();
    process.exit(0);
});

process.on('SIGTERM', () => {
    console.log('\n👋 Received SIGTERM, shutting down gracefully...');
    client.shutdown();
    process.exit(0);
});

// Start the client
const client = new SidecarClient();
client.start().catch(console.error);
